638	#[comemo::memoize]
639	pub fn localized_str(lang: Lang, region: Option<Region>, key: &str) -> &'static str {
640	    let lang_region_bundle = parse_language_bundle(lang, region).unwrap();
641	    if let Some(str) = lang_region_bundle.get(key) {
642	        return str;
643	    }
644	    let lang_bundle = parse_language_bundle(lang, None).unwrap();
645	    if let Some(str) = lang_bundle.get(key) {
