652	/// Parses the translation file for a given language and region.
653	/// Only returns an error if the language file is malformed.
654	#[comemo::memoize]
655	fn parse_language_bundle(
656	    lang: Lang,
657	    region: Option<Region>,
658	) -> Result<FxHashMap<&'static str, &'static str>, &'static str> {
659	    let language_tuple = TRANSLATIONS.iter().find(|it| it.0 == lang_str(lang, region));
660	    let Some((_lang_name, language_file)) = language_tuple else {
661	        return Ok(FxHashMap::default());
662	    };
663	
664	    let mut bundle = FxHashMap::default();
665	    let lines = language_file.trim().lines();
666	    for line in lines {
667	        if line.trim().starts_with('#') {
668	            continue;
669	        }
670	        let (key, val) = line
671	            .split_once('=')
672	            .ok_or("malformed translation file: line without \"=\"")?;
673	        let (key, val) = (key.trim(), val.trim());
674	        if val.is_empty() {
675	            return Err("malformed translation file: empty translation value");
676	        }
677	        let duplicate = bundle.insert(key.trim(), val.trim());
678	        if duplicate.is_some() {
679	            return Err("malformed translation file: duplicate key");
680	        }
681	    }
682	    Ok(bundle)
683	}
