370	    let value = value.as_slice();
371	    if value.len() != 2 {
372	        bail!(
373	            "expected 2 quotes, found {} quote{}",
374	            value.len(),
375	            if value.len() > 1 { "s" } else { "" },
376	        );
377	    }
378	
379	    let open: EcoString = value[0].clone().cast()?;
380	    let close: EcoString = value[1].clone().cast()?;
381	
